// Expected diagnostic code(s): O3S216.
module NegativeTypeSemanticTypedObjectReceiverUnknownMessage;

@interface Widget
@property (readonly) id token;
- (id) title;
@end

@implementation Widget
- (id) title {
  return nil;
}
@end

fn consume(widget: Widget *?) -> i32 {
  let token = [widget? token];
  let ok = [widget? title];
  let missing = [widget? missingTitle];
  return 0;
}
